import datetime
import re

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}


def _normalize_email(raw):
    """Return the normalized email, or None if it is not valid."""
    email = (raw or "").strip().lower()
    if email.count("@") != 1:
        return None
    local, domain = email.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.split("+", 1)[0].replace(".", "")
        domain = "gmail.com"
    if not local:
        return None
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None
    return f"{local}@{domain}"


def _normalize_phone(raw):
    """Return the normalized 10-digit phone, or None if it is not valid."""
    digits = "".join(c for c in (raw or "") if c in "0123456789")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits if len(digits) == 10 else None


def dedupe_contacts(rows):
    # Step 4: keep only rows with a valid email or phone.
    kept = []
    for row in rows:
        email = _normalize_email(row.get("email"))
        phone = _normalize_phone(row.get("phone"))
        if email is None and phone is None:
            continue
        kept.append({
            "first": (row.get("first_name") or "").strip(),
            "last": (row.get("last_name") or "").strip(),
            "zip": (row.get("zip") or "").strip(),
            "email": email,
            "phone": phone,
            "last_key": (row.get("last_name") or "").strip().lower(),
            "tags": {
                t.strip().lower()
                for t in (row.get("tags") or "").split(";")
                if t.strip()
            },
            "opted_out": (row.get("opted_out") or "").strip().upper() == "Y",
            "date": datetime.date.fromisoformat(row["updated"].strip()),
        })

    # Step 5: union-find over matching rows (transitive).
    parent = list(range(len(kept)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone_last = {}
    for i, entry in enumerate(kept):
        if entry["email"] is not None:
            key = entry["email"]
            if key in first_by_email:
                union(first_by_email[key], i)
            else:
                first_by_email[key] = i
        if entry["phone"] is not None and entry["last_key"]:
            key = (entry["phone"], entry["last_key"])
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    groups = {}
    for i in range(len(kept)):
        groups.setdefault(find(i), []).append(i)

    # Step 7: order people by their earliest input row.
    # Member indices are appended in increasing order, so idxs[0] is earliest.
    ordered_groups = sorted(groups.values(), key=lambda idxs: idxs[0])

    def pick(order, field):
        """Value of `field` from the first row in `order` where it is non-empty."""
        for i in order:
            value = kept[i][field]
            if value:
                return value
        return ""

    result = []
    for idxs in ordered_groups:
        # Most recent first; ties go to the earlier input row.
        order = sorted(idxs, key=lambda i: (-kept[i]["date"].toordinal(), i))

        tags = set()
        for i in idxs:
            tags |= kept[i]["tags"]

        result.append({
            "first_name": pick(order, "first"),
            "last_name": pick(order, "last"),
            "email": pick(order, "email"),
            "phone": pick(order, "phone"),
            "zip": pick(order, "zip"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(kept[i]["opted_out"] for i in idxs) else "N",
            "updated": max(kept[i]["date"] for i in idxs).isoformat(),
        })

    return result
